import { defineMiddleware } from 'astro:middleware';

// Content Security Policy applied to every HTML response generated by the
// Astro worker. We can't rely on public/_headers for this because that file
// only applies to static asset responses served via the Cloudflare ASSETS
// binding; on-demand routes (everything with `prerender = false`, which is
// every HTML page in this site) generate their responses through the Worker
// and bypass _headers entirely. So we set the CSP here.
//
// public/_headers still carries the same CSP as a fallback for static asset
// responses — belt-and-suspenders for files served directly off the bucket.
// Keep the two in sync when changing the policy.
const CSP = [
  "default-src 'none'",
  "style-src 'self' 'unsafe-inline'",
  "img-src 'self'",
  "font-src 'self'",
  "connect-src 'self'",
  "base-uri 'none'",
  "form-action 'none'",
  "frame-ancestors 'none'",
  "require-trusted-types-for 'script'",
  'upgrade-insecure-requests',
].join('; ');

export const onRequest = defineMiddleware(async (context, next) => {
  const response = await next();
  const contentType = response.headers.get('content-type') ?? '';
  if (contentType.includes('text/html')) {
    response.headers.set('Content-Security-Policy', CSP);
  }
  return response;
});
